"use strict";(function($){var acf=window.acf;var nvisACFData=window.nvisACFData;if(typeof acf==="undefined"){console.warn("acf.js not loaded.");return}if(typeof nvisACFData==="undefined"){console.warn("nvis-acf.js not localized properly.");return}var nvisACF=window.nvisACF={collegesFieldKey:"field_611279af182d2",departmentsFieldKey:"field_630fb69367bc5",departmentLoaded:null,collegesDepartments:{},prepareCollege:function prepareCollege(field){field.$el.on("select2:select",function(e){nvisACF.collegeSet(e.params.data.id)})},loadDepartment:function loadDepartment(field){var college=acf.getField(nvisACF.collegesFieldKey);if(field.val()&&!nvisACF.departmentLoaded){nvisACF.departmentLoaded=Number(field.val())}if(!college.val()){field.disable()}else{field.enable();nvisACF.collegeSet(college.val())}},collegeSet:function collegeSet(collegeID){if(typeof nvisACF.collegesDepartments[collegeID]!=="undefined"){nvisACF.setDepartments(nvisACF.collegesDepartments[collegeID])}else{$.post(nvisACFData.ajax_url,{_ajax_nonce:nvisACFData.nonce,action:"get_college_departments",college:collegeID},function(data){nvisACF.collegesDepartments[collegeID]=data;nvisACF.setDepartments(data)})}},setDepartments:function setDepartments(newOptions){var field=acf.getField(nvisACF.departmentsFieldKey);var $select=$("select",field.$el);$select.val(null).empty().trigger("change");if(typeof newOptions!=="undefined"){if(newOptions.length){$select.append(new Option(field.data.placeholder,0,false,false));newOptions.forEach(function(opt){var selected=opt.term_id===nvisACF.departmentLoaded;$select.append(new Option(opt.name,opt.term_id,selected,selected)).trigger("change")});field.enable()}else{$select.append(new Option(nvisACFData.label_not_found,0)).trigger("change");field.disable()}}$select.trigger("change")}};acf.addAction("prepare_field/key="+nvisACF.collegesFieldKey,nvisACF.prepareCollege);acf.addAction("load_field/key="+nvisACF.departmentsFieldKey,nvisACF.loadDepartment)})(window.jQuery);
